15	  XML: /^[\w\-.+]+\/([\w\-.+]+\+)?xml$/,
16	  // Matches: text/html
17	  // Pattern: type/([base]+)?suffix where suffix is html
18	  HTML: /^[\w\-.+]+\/([\w\-.+]+\+)?html$/
19	};
