95	/**
96	 * Determines the body type based on content-type from OpenAPI spec
97	 * Uses pattern matching to handle various MIME type variants (e.g., application/ld+json, application/vnd.api+json)
98	 * @param {string} contentType - The content-type from OpenAPI spec (object key, e.g., "application/json")
99	 * @returns {string} - The body type (json, xml, html, text)
100	 */
101	const getBodyTypeFromContentType = (contentType) => {
102	  if (!contentType || typeof contentType !== 'string') {
103	    return 'text';
104	  }
105	
106	  // Normalize: lowercase (object keys may vary in case, but shouldn't have parameters or whitespace)
107	  const normalizedContentType = contentType.toLowerCase();
108	
109	  if (CONTENT_TYPE_PATTERNS.JSON.test(normalizedContentType)) {
110	    return 'json';
111	  } else if (CONTENT_TYPE_PATTERNS.XML.test(normalizedContentType)) {
112	    return 'xml';
113	  } else if (CONTENT_TYPE_PATTERNS.HTML.test(normalizedContentType)) {
114	    return 'html';
115	  }
116	
117	  return 'text';
118	};
