120	/**
121	 * Gets a default value for a schema based on its type, format, and constraints
122	 * Prioritizes: explicit example > enum first value > format-specific example > type default
123	 * @param {Object} schema - The OpenAPI schema object
124	 * @param {Map} visited - Map to track circular references
125	 * @returns {*} - The default value for the schema
126	 */
127	const getDefaultValueForSchema = (schema, visited = new Map()) => {
128	  // Check for explicit example first
129	  if (schema.example !== undefined) {
130	    return schema.example;
131	  }
132	
133	  // Check for enum and use first value
134	  if (schema.enum && schema.enum.length > 0) {
135	    return schema.enum[0];
136	  }
137	
138	  // Handle different types
139	  if (schema.type === 'object' || schema.properties) {
140	    return buildEmptyJsonBody(schema, visited);
141	  }
142	
143	  if (schema.type === 'array') {
144	    // Check for array-level example
145	    if (schema.example !== undefined) {
146	      return schema.example;
147	    }
148	
149	    if (schema.items) {
150	      if (schema.items.type === 'object' || schema.items.properties) {
151	        return [buildEmptyJsonBody(schema.items, visited)];
152	      }
153	      // For primitive arrays, get example from items
154	      if (schema.items.example !== undefined) {
155	        return Array.isArray(schema.items.example) ? schema.items.example : [schema.items.example];
156	      }
157	      // Return array with a single default primitive value
158	      const itemDefault = getDefaultValueForSchema(schema.items, visited);
159	      if (itemDefault !== '' && itemDefault !== 0 && itemDefault !== false) {
160	        return [itemDefault];
161	      }
162	    }
163	    return [];
164	  }
165	
166	  if (schema.type === 'integer' || schema.type === 'number') {
167	    return 0;
168	  }
169	
170	  if (schema.type === 'boolean') {
171	    return false;
172	  }
173	
174	  // Default for strings and other types
175	  return '';
176	};
